<?php
require 'config/koneksi.php'; require_role(['customer']); $pageTitle='Keranjang';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['update'])){foreach(($_POST['qty']??[]) as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if($qty<=0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=$qty;}$_SESSION['flash']='Keranjang diperbarui.';header('Location: keranjang.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['checkout'])){$cart=$_SESSION['cart']??[];$method=($_POST['payment_method']??'Tunai')==='QRIS'?'QRIS':'Tunai';$notes=trim($_POST['notes']??'');$items=[];$total=0;
 foreach($cart as $id=>$qty){$st=$conn->prepare('SELECT id,name,price,stock FROM products WHERE id=?');$id=(int)$id;$st->bind_param('i',$id);$st->execute();$p=$st->get_result()->fetch_assoc();$qty=(int)$qty;if(!$p||$qty<1||$p['stock']<$qty){$_SESSION['flash']='Stok salah satu menu tidak mencukupi. Perbarui keranjang.';header('Location: keranjang.php');exit;}$p['qty']=$qty;$p['subtotal']=$qty*(float)$p['price'];$items[]=$p;$total+=$p['subtotal'];}
 if(!$items){$_SESSION['flash']='Keranjang masih kosong.';header('Location: keranjang.php');exit;}
 $conn->begin_transaction();try{$code='WEB'.date('ymdHis').random_int(10,99);$uid=(int)$_SESSION['user']['id'];$st=$conn->prepare('INSERT INTO orders(order_code,user_id,total,payment_method,notes) VALUES(?,?,?,?,?)');$st->bind_param('sidss',$code,$uid,$total,$method,$notes);$st->execute();$oid=$conn->insert_id;$it=$conn->prepare('INSERT INTO order_items(order_id,product_id,product_name,qty,price,subtotal) VALUES(?,?,?,?,?,?)');foreach($items as $p){$it->bind_param('iisidd',$oid,$p['id'],$p['name'],$p['qty'],$p['price'],$p['subtotal']);$it->execute();}$conn->commit();unset($_SESSION['cart']);$_SESSION['flash']='Pesanan '.$code.' berhasil dibuat. Menunggu konfirmasi.';header('Location: pesanan.php');exit;}catch(Throwable $e){$conn->rollback();$_SESSION['flash']='Pesanan gagal disimpan. Coba kembali.';header('Location: keranjang.php');exit;}}
$cart=$_SESSION['cart']??[];$items=[];$total=0;foreach($cart as $id=>$qty){$id=(int)$id;$st=$conn->prepare('SELECT id,name,price,stock FROM products WHERE id=?');$st->bind_param('i',$id);$st->execute();$p=$st->get_result()->fetch_assoc();if($p){$p['qty']=(int)$qty;$p['subtotal']=$p['qty']*$p['price'];$items[]=$p;$total+=$p['subtotal'];}}require 'includes/header.php'; ?>
<div class="page-heading"><div><h1>Keranjang Belanja</h1><p>Periksa pesanan sebelum checkout.</p></div><a class="btn light" href="customer.php">← Kembali ke Menu</a></div>
<?php if(!$items): ?><section class="panel empty">Keranjang kamu masih kosong. <a href="customer.php"><strong>Lihat menu</strong></a></section><?php else: ?><section class="panel"><form method="post"><div class="table-wrap"><table><thead><tr><th>Menu</th><th>Harga</th><th>Jumlah</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= rupiah($p['price']) ?></td><td><input type="number" name="qty[<?= $p['id'] ?>]" min="0" max="<?= (int)$p['stock'] ?>" value="<?= $p['qty'] ?>" style="width:75px;padding:7px"></td><td><?= rupiah($p['subtotal']) ?></td></tr><?php endforeach; ?></tbody></table></div><button class="btn light" name="update" value="1" style="margin-top:14px">Perbarui Keranjang</button></form><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><h3>Total: <?= rupiah($total) ?></h3><form method="post"><div class="form-grid"><div class="field"><label>Metode Pembayaran</label><select name="payment_method"><option>Tunai</option><option>QRIS</option></select></div><div class="field"><label>Catatan Pesanan (opsional)</label><input name="notes" maxlength="255" placeholder="Contoh: gula sedikit"></div></div><div class="form-actions"><button class="btn" name="checkout" value="1">Buat Pesanan</button></div><p style="font-size:11px;color:var(--muted)">Pembayaran dilakukan saat pesanan diambil. Stok diperiksa kembali ketika pesanan diproses.</p></form></section><?php endif; ?>
<?php require 'includes/footer.php'; ?>
